# Solution for the soldier redistribution problem

import sys
from collections import deque

class FlowNetwork:
    def __init__(self, n):
        self.n = n
        self.source = 0
        self.sink = 2 * n + 1
        self.capacity = {}
        self.flow = {}
        self.graph = {}
        for i in range(self.source + 1, self.sink):
            self.capacity[i] = {}
            self.flow[i] = {}
            self.graph[i] = []

    def add_edge(self, u, v, capacity):
        if u not in self.capacity:
            self.capacity[u] = {}
            self.flow[u] = {}
            self.graph[u] = []
        if v not in self.capacity:
            self.capacity[v] = {}
            self.flow[v] = {}
            self.graph[v] = []

        self.capacity[u][v] = self.capacity[u].get(v, 0) + capacity
        self.capacity[v][u] = self.capacity[v].get(u, 0)

        self.flow[u][v] = self.flow[u].get(v, 0)
        self.flow[v][u] = self.flow[v].get(u, 0)

        self.graph[u].append(v)
        self.graph[v].append(u)

    def bfs(self, path):
        visited = {self.source}
        parent = {self.source: None}
        queue = deque([self.source])

        while queue:
            u = queue.popleft()
            if u == self.sink:
                break

            if u in self.capacity:
                for v in self.graph[u]:
                    if v not in visited and self.capacity[u].get(v, 0) - self.flow[u].get(v, 0) > 0:
