2. Find the minimum number of roads needed to merge components to form a lucky-number-sized region
3. A lucky number contains only digits 4 and 7

The approach:
1. Parse input and build adjacency list
2. Use BFS to find all connected components and their sizes
3. Generate all lucky numbers up to n
4. Use DP to find minimum components that sum to each reachable size
5. Find minimum roads = min(dp[lucky] - 1) for all lucky numbers

```python
from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    header = lines[0].split()
    n, m = int(header[0]), int(header[1])

    adj = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            queue = deque([i])
            visited[i] = True
            size = 0
            while queue:
                node = queue.popleft()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            component_sizes.append(size)

    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for size in component_sizes:
        for s in range(n, size - 1, -1):
            if dp[s - size] != float('inf'):
                dp[s] = min(dp[s], dp[s - size] + 1)

    lucky_numbers = []
    def generate_lucky(current):
        if current > n:
            return
        if current > 0:
            lucky_numbers.append(current)
        for digit in [4, 7]:
            new_current = current * 10 + digit
            if new_current <= n:
                generate_lucky(new_current)

    generate_lucky(0)
    lucky_numbers = sorted(lucky_numbers)

    min_roads = float('inf')
    for lucky in lucky_numbers:
        if dp[lucky] != float('inf') and dp[lucky] >= 2:
            min_roads = min(min_roads, dp[lucky] - 1)

    if min_roads == float('inf'):
        return '-1\n'
    return str(min_roads) + '\n'
